SELECT o.*, p.title AS productTitle, p.image_path AS productImage, u_seller.username AS sellerName FROM orders o LEFT JOIN products p ON o.product_id = p.id LEFT JOIN users u_seller ON o.seller_id = u_seller.id WHERE o.buyer_id = #{buyerId}
AND o.status = #{dto.status}
ORDER BY o.created_at DESC

